{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const rows = [];
  for (const issue of issues) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: issue.id });
    // newest first already, but be defensive
    const sorted = [...events].sort((a, b) => (a.timestamp < b.timestamp ? 1 : a.timestamp > b.timestamp ? -1 : 0));
    rows.push({
      shortId: issue.shortId,
      count: issue.count,
      status: issue.status,
      latestRelease: sorted.length ? sorted[0].release : null,
      _eventCount: events.length,
    });
  }
  rows.sort((a, b) => b.count - a.count);
  return { issueCount: issues.length, rows };
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const detail = [];
  for (const issue of issues) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: issue.id });
    if (events.length > 1) {
      detail.push({ shortId: issue.shortId, events });
    }
  }
  return { multiEventIssues: detail };
}"}
